update public.case_questions set answer_core='request Authorization header',aliases='["authorization header", "request header", "request headers"]'::jsonb,required_groups=null,patterns='[]'::jsonb,answer_reason='The key is visible in the outgoing request’s Authorization header. Response headers are sent back by the server and are not where this request sends the key. Minifying or obfuscating the bundle does not hide the key when it is sent.' where id=11 and concept_id=3;
